&lt;ul&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Bachelor&#39;s degree (BSc) preferred&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
